/// `test numbers_start_at_one` (src/todo/tests/scenarios.slg:8:1).
#[test]
fn numbers_start_at_one() {
    let mut world = World::default();
    let mut out = Out::default();
    assert_eq!(
        board::add(
            &mut world,
            &mut out,
            Title::new("milk").expect("a Title"),
            Priority::Normal,
            BTreeSet::new(),
        ),
        TaskNo::from_proven(1),
    );
    assert_eq!(
        board::add(
            &mut world,
            &mut out,
            Title::new("bread").expect("a Title"),
            Priority::Normal,
            BTreeSet::from([
                Tag::new("shop").expect("a Tag"),
                Tag::new("home").expect("a Tag"),
            ]),
        ),
        TaskNo::from_proven(2),
    );
    assert_eq!(out.text(), "added 1\nadded 2\n");
}
/// `test numbers_are_never_reused` (src/todo/tests/scenarios.slg:14:1).
#[test]
fn numbers_are_never_reused() {
    let mut world = World::default();
    let mut out = Out::default();
    assert_eq!(
        board::add(
            &mut world,
            &mut out,
            Title::new("a").expect("a Title"),
            Priority::Normal,
            BTreeSet::new(),
        ),
        TaskNo::from_proven(1),
    );
    assert_eq!(
        board::add(
            &mut world,
            &mut out,
            Title::new("b").expect("a Title"),
            Priority::Normal,
            BTreeSet::new(),
        ),
        TaskNo::from_proven(2),
    );
    board::remove(&mut world, &mut out, TaskNo::from_proven(2))
        .expect("todo.tests.scenarios.numbers_are_never_reused is not refused");
    assert_eq!(
        board::add(
            &mut world,
            &mut out,
            Title::new("c").expect("a Title"),
            Priority::Normal,
            BTreeSet::new(),
        ),
        TaskNo::from_proven(3),
    );
}
