/// `test done_and_reopen_move_once` (src/todo/tests/scenarios.slg:39:1).
#[test]
fn done_and_reopen_move_once() {
    let mut world = support::three_open_one_done();
    let mut out = Out::default();
    board::done(&mut world, &mut out, TaskNo::from_proven(2))
        .expect("todo.tests.scenarios.done_and_reopen_move_once is not refused");
    assert_eq!(
        board::done(&mut world, &mut out, TaskNo::from_proven(2)),
        Err(Refusal::AlreadyDone),
    );
    board::reopen(&mut world, &mut out, TaskNo::from_proven(2))
        .expect("todo.tests.scenarios.done_and_reopen_move_once is not refused");
    assert_eq!(
        board::reopen(&mut world, &mut out, TaskNo::from_proven(2)),
        Err(Refusal::NotDone),
    );
    assert_eq!(out.text(), "2 [x] plain\n2 [ ] plain\n");
}
/// `test rename_keeps_the_rest` (src/todo/tests/scenarios.slg:48:1).
#[test]
fn rename_keeps_the_rest() {
    let mut world = support::three_open_one_done();
    let mut out = Out::default();
    board::rename(
            &mut world,
            &mut out,
            TaskNo::from_proven(3),
            Title::new("urgent, really").expect("a Title"),
        )
        .expect("todo.tests.scenarios.rename_keeps_the_rest is not refused");
    assert_eq!(
        world.tasks[&TaskNo::from_proven(3)],
        Task {
            no: TaskNo::from_proven(3),
            title: Title::new("urgent, really").expect("a Title"),
            status: Status::Open,
            priority: Priority::High,
            tags: BTreeSet::from([Tag::new("work").expect("a Tag")]),
        },
    );
}
/// `test clear_removes_only_done` (src/todo/tests/scenarios.slg:54:1).
#[test]
fn clear_removes_only_done() {
    let mut world = support::three_open_one_done();
    let mut out = Out::default();
    assert_eq!(board::clear(&mut world, &mut out), 1);
    board::stats(&board::StatsView::of(&world), &mut out);
    assert_eq!(out.text(), "cleared 1\n3 open, 0 done\n");
    assert!(!world.tasks.contains_key(&TaskNo::from_proven(4)));
}
/// `test unknown_numbers_are_refused` (src/todo/tests/scenarios.slg:62:1).
#[test]
fn unknown_numbers_are_refused() {
    fn case(no: TaskNo) {
        let mut world = support::three_open_one_done();
        let mut out = Out::default();
        if no.get() <= 4 {
            return;
        }
        assert_eq!(board::done(&mut world, &mut out, no), Err(Refusal::NoTask));
        assert_eq!(board::reopen(&mut world, &mut out, no), Err(Refusal::NoTask));
        assert_eq!(
            board::rename(&mut world, &mut out, no, Title::new("x").expect("a Title")),
            Err(Refusal::NoTask),
        );
        assert_eq!(board::remove(&mut world, &mut out, no), Err(Refusal::NoTask));
        assert_eq!(out.text(), "");
    }
    let mut rng = support::Rng::new(0);
    for _ in 0..300 {
        let no = support::task_no(&mut rng);
        case(no);
    }
}
